<script setup lang="ts">
import { computed, onMounted, ref } from "vue";
import { http } from "@/utils/http";
type Vault = { id: string; name?: string; status?: string }; type Note = { id: string; revision?: number; tombstone?: boolean; updatedAt?: string };
const vault = ref<Vault | null>(null); const notes = ref<Note[]>([]); const loading = ref(false); const error = ref(""); const dialog = ref(false); const unlocking = ref(false); const unlockCode = ref(""); const locked = ref(true); const search = ref(""); const selected = ref<Note | null>(null); const draftTitle = ref(""); const draftContent = ref(""); const saveState = ref("已保存");
const visibleNotes = computed(() => notes.value.filter(note => !search.value || note.id.toLowerCase().includes(search.value.toLowerCase())));
async function load() { loading.value = true; error.value = ""; try { const result = await http.get<unknown, unknown>("/private-notes/vaults"); const values = Array.isArray(result) ? result as Vault[] : []; vault.value = values[0] || null; locked.value = !vault.value || String(vault.value.status).toUpperCase() !== "UNLOCKED"; if (vault.value && !locked.value) await loadNotes(); } catch (e: any) { error.value = e?.response?.data?.detail || e?.message || "私密保险库状态加载失败"; } finally { loading.value = false; } }
async function loadNotes() { if (!vault.value) return; const result = await http.get<unknown, unknown>(`/private-notes/vaults/${vault.value.id}/notes`); notes.value = Array.isArray(result) ? result as Note[] : []; }
async function unlock() { if (!vault.value) { error.value = "暂无可用保险库"; return; } unlocking.value = true; try { const result = await http.post<unknown, unknown>(`/private-notes/vaults/${vault.value.id}/actions/unlock`, { data: { code: unlockCode.value || undefined } }); vault.value = result as Vault; locked.value = false; dialog.value = false; unlockCode.value = ""; await loadNotes(); } catch (e: any) { error.value = "解锁失败，请稍后重试"; } finally { unlocking.value = false; } }
async function lock() { if (!vault.value) return; try { await http.post(`/private-notes/vaults/${vault.value.id}/actions/lock`); notes.value = []; locked.value = true; } catch (e: any) { error.value = e?.response?.data?.detail || e?.message || "保险库锁定失败"; } }
onMounted(load);
</script>
<template><main class="p-4 md:p-6"><template v-if="loading"><el-skeleton :rows="8" animated/></template><template v-else-if="locked"><el-card shadow="never" class="max-w-xl mx-auto mt-12 text-center"><div class="text-5xl mb-4">🔒</div><h1 class="text-2xl font-semibold">私密笔记已锁定</h1><p class="mt-3 text-[var(--el-text-color-secondary)]">解锁保险库后才能查看和编辑私密笔记。</p><el-alert v-if="error" :title="error" type="error" show-icon :closable="false" class="my-4 text-left"/><el-button type="primary" class="mt-4" @click="dialog = true">解锁保险库</el-button></el-card></template><template v-else><div class="flex justify-between items-start gap-4 mb-6"><div><h1 class="text-2xl font-semibold">私密笔记</h1><p class="mt-1 text-[var(--el-text-color-secondary)]">内容仅在当前已解锁保险库上下文中可见 · 自动锁定策略由服务端控制。</p></div><div class="flex gap-2"><el-input v-model="search" placeholder="仅在保险库内搜索" clearable class="w-52"/><el-button type="primary">新建私密笔记</el-button><el-button circle title="立即锁定" @click="lock">🔒</el-button></div></div><el-alert v-if="error" :title="error" type="error" show-icon :closable="false" class="mb-4"/><div class="grid grid-cols-1 lg:grid-cols-5 gap-5"><el-card shadow="never"><template #header>Folder / 类型</template><el-menu default-active="all"><el-menu-item index="all">全部笔记</el-menu-item><el-menu-item index="favorites">收藏</el-menu-item><el-menu-item index="conflicts">同步冲突</el-menu-item></el-menu></el-card><el-card shadow="never" class="lg:col-span-2"><template #header><div class="flex justify-between"><span>笔记列表</span><el-tag size="small">{{ saveState }}</el-tag></div></template><el-empty v-if="!visibleNotes.length" description="暂无私密笔记"/><div v-for="note in visibleNotes" :key="note.id" class="py-3 border-b last:border-0 cursor-pointer" @click="selected = note; draftTitle = `私密笔记 · ${note.id.slice(0, 8)}`"><div class="font-medium">私密笔记 · {{ note.id.slice(0, 8) }}</div><div class="text-xs text-[var(--el-text-color-secondary)] mt-1">修订 {{ note.revision ?? 0 }} · {{ note.updatedAt || '未同步' }}</div></div></el-card><el-card shadow="never" class="lg:col-span-2"><template #header><div class="flex justify-between"><span>编辑器 / 预览</span><span class="text-xs text-[var(--el-text-color-secondary)]">{{ saveState }}</span></div></template><template v-if="selected"><el-input v-model="draftTitle" placeholder="标题（必填）" class="mb-3" @input="saveState = '离线修改'"/><el-input v-model="draftContent" type="textarea" :rows="12" placeholder="在此编辑加密内容" @input="saveState = '离线修改'"/><div class="flex flex-wrap gap-2 mt-3"><el-select placeholder="Folder / Collection" class="w-44" disabled/><el-tag>私密上下文</el-tag><el-button size="small" @click="saveState = '已保存'">保存</el-button></div></template><el-empty v-else description="选择笔记后在此编辑"/></el-card></div></template><el-dialog v-model="dialog" title="解锁保险库" width="420px"><p class="text-sm text-[var(--el-text-color-secondary)] mb-4">需要完成认证后才能进入私密上下文。</p><el-input v-model="unlockCode" type="password" placeholder="解锁凭据（不会保存）" show-password/><template #footer><el-button @click="dialog = false">取消</el-button><el-button type="primary" :loading="unlocking" @click="unlock">解锁</el-button></template></el-dialog></main></template>
